// ── Helpers (hand-written, below the generated data) ────────────────────────

/** Mirrors InspectionPricing._titleCase, hyphens included: "isale-eko" → "Isale-Eko". */
export function areaDisplayName(area: string): string {
  return area
    .split(' ')
    .map((w) =>
      ['vi', 'vgc', 'gra', 'bq', 'lasu', 'cms'].includes(w.toLowerCase())
        ? w.toUpperCase()
        : w.replace(/(^|[-/])([a-z])/g, (_, sep, c) => sep + c.toUpperCase()),
    )
    .join(' ')
}

/**
 * The state an LGA sits in, from the generated table. Null for an LGA with no
 * state (the `other` bucket, or one published without one): the caller must not
 * assume Lagos, which is how out-of-state listings were saved as Lagos.
 */
export function stateForLga(lga: string, remote?: RemoteLgas): string | null {
  return LGA_STATE[lga] || remote?.[lga]?.state || null
}

/** "Ikeja LGA" → "Ikeja", "Lagos outskirts: Obafemi-Owode (Ogun)" → "Obafemi-Owode". */
export function lgaName(lga: string): string {
  return (LGA_LABELS[lga] ?? lga)
    .replace(/^Lagos outskirts:\s*/, '')
    .replace(/\s*\((Ogun|Lagos)\)$/, '')
    .replace(/\s+LGA$/, '')
}

/** The area an old spelling means, or the name itself. */
export function canonicalArea(area: string): string {
  const key = area.trim().toLowerCase()
  return AREA_TO_LGA[key] ? key : (AREA_ALIASES[key] ?? key)
}

type RemoteLgas = Record<string, { label?: string; state?: string }>

/** States we carry areas for, in display order. */
export function statesWithAreas(remote?: RemoteLgas): string[] {
  const states: string[] = []
  for (const lga of [...LGA_ORDER, ...Object.keys(remote ?? {})]) {
    const state = stateForLga(lga, remote)
    if (state && !states.includes(state)) states.push(state)
  }
  return states
}

/**
 * Areas grouped by LGA for one state, with config/areas merged over the
 * compiled list exactly as the app does, including LGAs published live.
 * Unreadable config falls back to the compiled list.
 */
export async function areaGroups(
  state: string,
): Promise<Array<{ lga: string; label: string; areas: string[] }>> {
  const merged: Record<string, string> = { ...AREA_TO_LGA }
  let remote: RemoteLgas = {}
  try {
    const { doc, getDoc } = await import('firebase/firestore')
    const { clientDb } = await import('./firebase-client')
    const data = (await getDoc(doc(clientDb(), 'config', 'areas'))).data()
    const remoteLgas = data?.lgas
    if (remoteLgas && typeof remoteLgas === 'object') {
      for (const [lga, meta] of Object.entries(remoteLgas as RemoteLgas)) {
        // Same rule as the app: no label or no state, no LGA.
        if (meta && typeof meta === 'object' && meta.label && meta.state) remote[lga] = meta
      }
    }
    const remoteAreas = data?.areas
    if (remoteAreas && typeof remoteAreas === 'object') {
      const known = new Set([...LGA_ORDER, ...Object.keys(remote), 'outer', 'other'])
      for (const [area, lga] of Object.entries(remoteAreas)) {
        if (typeof lga === 'string' && known.has(lga)) merged[area.trim().toLowerCase()] = lga
      }
    }
  } catch {
    remote = {}
  }
  const order = [...LGA_ORDER, ...Object.keys(remote)]
  const byLga = new Map<string, string[]>()
  for (const [area, lga] of Object.entries(merged)) {
    if (stateForLga(lga, remote) !== state) continue
    byLga.set(lga, [...(byLga.get(lga) ?? []), area])
  }
  return [...byLga.entries()]
    .map(([lga, areas]) => ({
      lga,
      label: LGA_LABELS[lga] ?? remote[lga]?.label ?? lga,
      areas: areas.sort(),
    }))
    .sort((a, b) => order.indexOf(a.lga) - order.indexOf(b.lga))
}
